const classCache = new Map();
const MAX_CACHE_SIZE = 500;
export const normalizeClasses = (...classes) => {
    if (classes.length === 0)
        return [];
    if (classes.length === 1 && typeof classes[0] === "string") {
        const input = classes[0];
        if (!input)
            return [];
        if (!input.includes(" "))
            return [input];
        if (classCache.has(input)) {
            return classCache.get(input);
        }
    }
    const seen = new Set();
    const result = [];
    for (const cls of classes) {
        if (typeof cls === "string" && cls) {
            if (!cls.includes(" ")) {
                if (!seen.has(cls)) {
                    seen.add(cls);
                    result.push(cls);
                }
            }
            else {
                cls.split(" ").forEach((c) => {
                    const trimmed = c.trim();
                    if (trimmed && !seen.has(trimmed)) {
                        seen.add(trimmed);
                        result.push(trimmed);
                    }
                });
            }
        }
        else if (Array.isArray(cls)) {
            cls.forEach((c) => {
                if (typeof c === "string" && c) {
                    c.split(" ").forEach((part) => {
                        const trimmed = part.trim();
                        if (trimmed && !seen.has(trimmed)) {
                            seen.add(trimmed);
                            result.push(trimmed);
                        }
                    });
                }
            });
        }
    }
    if (classes.length === 1 &&
        typeof classes[0] === "string" &&
        result.length <= 10) {
        if (classCache.size < MAX_CACHE_SIZE) {
            classCache.set(classes[0], result);
        }
    }
    return result;
};
export const addClass = (element, ...classes) => {
    if (classes.length === 0)
        return element;
    if (classes.length === 1 && Array.isArray(classes[0])) {
        return addClass(element, ...classes[0]);
    }
    if (classes.length === 1 && typeof classes[0] === "string") {
        const cls = classes[0];
        if (cls && !cls.includes(" ")) {
            const prefixed = cls;
            if (!prefixed.includes(" ")) {
                element.classList.add(prefixed);
                return element;
            }
        }
    }
    const normalized = normalizeClasses(...classes);
    for (const cls of normalized) {
        const prefixed = cls;
        if (prefixed.includes(" ")) {
            prefixed.split(" ").forEach((c) => {
                const trimmed = c.trim();
                if (trimmed)
                    element.classList.add(trimmed);
            });
        }
        else {
            element.classList.add(prefixed);
        }
    }
    return element;
};
export const removeClass = (element, ...classes) => {
    if (classes.length === 0)
        return element;
    if (classes.length === 1 && Array.isArray(classes[0])) {
        return removeClass(element, ...classes[0]);
    }
    if (classes.length === 1 && typeof classes[0] === "string") {
        const cls = classes[0];
        if (cls && !cls.includes(" ")) {
            const prefixed = cls;
            if (!prefixed.includes(" ")) {
                element.classList.remove(prefixed);
                return element;
            }
        }
    }
    const normalized = normalizeClasses(...classes);
    for (const cls of normalized) {
        const prefixed = cls;
        if (prefixed.includes(" ")) {
            prefixed.split(" ").forEach((c) => {
                const trimmed = c.trim();
                if (trimmed)
                    element.classList.remove(trimmed);
            });
        }
        else {
            element.classList.remove(prefixed);
        }
    }
    return element;
};
export const toggleClass = (element, ...classes) => {
    if (classes.length === 1 && Array.isArray(classes[0])) {
        return toggleClass(element, ...classes[0]);
    }
    if (classes.length === 1 && typeof classes[0] === "string") {
        const cls = classes[0];
        if (cls && !cls.includes(" ")) {
            const prefixed = cls;
            if (!prefixed.includes(" ")) {
                element.classList.toggle(prefixed);
                return element;
            }
        }
    }
    const normalized = normalizeClasses(...classes);
    for (const cls of normalized) {
        const prefixed = cls;
        if (prefixed.includes(" ")) {
            prefixed.split(" ").forEach((c) => {
                const trimmed = c.trim();
                if (trimmed)
                    element.classList.toggle(trimmed);
            });
        }
        else {
            element.classList.toggle(prefixed);
        }
    }
    return element;
};
export const hasClass = (element, ...classes) => {
    if (classes.length === 0)
        return true;
    if (classes.length === 1 && Array.isArray(classes[0])) {
        return hasClass(element, ...classes[0]);
    }
    if (classes.length === 1 && typeof classes[0] === "string") {
        const cls = classes[0];
        if (cls && !cls.includes(" ")) {
            const prefixed = cls;
            if (!prefixed.includes(" ")) {
                return element.classList.contains(prefixed);
            }
        }
    }
    const normalized = normalizeClasses(...classes);
    for (const cls of normalized) {
        const prefixed = cls;
        if (prefixed.includes(" ")) {
            const tokens = prefixed
                .split(" ")
                .map((c) => c.trim())
                .filter(Boolean);
            for (const token of tokens) {
                if (!element.classList.contains(token)) {
                    return false;
                }
            }
        }
        else {
            if (!element.classList.contains(prefixed)) {
                return false;
            }
        }
    }
    return true;
};
